-- Run once against the PostgreSQL database configured as DATABASE_URL.
CREATE TABLE IF NOT EXISTS "user" (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, "emailVerified" boolean NOT NULL DEFAULT false, image text, "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "session" (id text PRIMARY KEY, "expiresAt" timestamp NOT NULL, token text NOT NULL UNIQUE, "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now(), "ipAddress" text, "userAgent" text, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "account" (id text PRIMARY KEY, "accountId" text NOT NULL, "providerId" text NOT NULL, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamp, "refreshTokenExpiresAt" timestamp, scope text, password text, "createdAt" timestamp NOT NULL DEFAULT now(), "updatedAt" timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "verification" (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, "expiresAt" timestamp NOT NULL, "createdAt" timestamp DEFAULT now(), "updatedAt" timestamp DEFAULT now());
CREATE TABLE IF NOT EXISTS firm_settings (id text PRIMARY KEY, firm_name text NOT NULL, tagline text, description text, logo_url text, address text, city text, state text, country text, phone text, email text, whatsapp text, maps_embed_url text, maps_directions_url text, business_hours text, service_areas text, social_links jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS projects (id serial PRIMARY KEY, slug text NOT NULL UNIQUE, title text NOT NULL, location text, year text, project_type text, status text, area text, short_description text, description text, concept text, cover_image text, gallery jsonb NOT NULL DEFAULT '[]'::jsonb, video_url text, maps_url text, published boolean NOT NULL DEFAULT false, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS services (id serial PRIMARY KEY, title text NOT NULL, slug text NOT NULL UNIQUE, summary text, details text, project_examples jsonb NOT NULL DEFAULT '[]'::jsonb, sort_order integer NOT NULL DEFAULT 0, published boolean NOT NULL DEFAULT true, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS media (id serial PRIMARY KEY, title text NOT NULL, kind text NOT NULL, url text NOT NULL, caption text, project_id integer REFERENCES projects(id) ON DELETE SET NULL, sort_order integer NOT NULL DEFAULT 0, published boolean NOT NULL DEFAULT true, created_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS inquiries (id serial PRIMARY KEY, name text NOT NULL, email text NOT NULL, phone text, project_type text, location text, size_or_budget text, message text NOT NULL, file_url text, status text NOT NULL DEFAULT 'new', created_at timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS inquiries_created_at_idx ON inquiries(created_at DESC);
CREATE INDEX IF NOT EXISTS projects_published_idx ON projects(published);
CREATE INDEX IF NOT EXISTS media_published_idx ON media(published);
